// 聊天窗第 1 步：把用户这一句话读成"他想干什么"
// 四个去向：query（问某地现状）/ classify（贴了一条微博要判）/ collect（下单去抓）/ status（问进度）/ help（不知道怎么用）
// 注意：这里只做路由判断，不花钱、不联网。真正干活在后面的分支。
const LEXICON = {"lexicon_version": "p2", "note": "地名判定词表。地点不再写死在『成都』：由调用方按用户提问给出 payload.scope.city（可附 aliases），本词表只负责两件事——① 已知城市的别名表；② 判断一段文本提到的是不是别的城市。匹配前会先按等长掩码盖掉 @昵称，避免『@某市官方账号』把外地帖判成本地。", "scope_contract": {"payload.scope": "{ city: '重庆', aliases: ['重庆','渝中区','解放碑'] }", "不传 scope 时": "不做地点过滤，location_scope 只标注文本里提到的城市（target / unknown），in_scope 一律 true", "传了 scope 时": "命中目标城市 → target；只命中别的地名 → other_place；没提地名 → unknown"}, "cities": {"成都": {"aliases": ["成都", "蓉城", "锦官城", "天府之国", "锦江区", "青羊区", "武侯区", "成华区", "金牛区", "高新区", "天府新区", "双流", "温江", "郫都", "新都", "龙泉驿", "青白江", "新津", "简阳", "都江堰", "彭州", "邛崃", "崇州", "金堂", "大邑", "蒲江", "春熙路", "太古里", "宽窄巷子", "人民公园", "天府广场", "环球中心", "九眼桥", "玉林", "建设路", "磨子桥", "华西坝", "文殊院", "兴隆湖", "交子大道", "东郊记忆", "熊猫基地", "锦里", "武侯祠"]}, "重庆": {"aliases": ["重庆", "渝中", "渝北", "江北", "沙坪坝", "九龙坡", "南岸", "北碚", "巴南", "大渡口", "璧山", "江津", "万州", "涪陵", "合川", "永川", "綦江", "长寿", "铜梁", "解放碑", "洪崖洞", "观音桥", "朝天门", "大学城", "两江新区"]}, "北京": {"aliases": ["北京", "三里屯", "国贸", "西单", "中关村", "望京", "回龙观", "通州"]}, "上海": {"aliases": ["上海", "陆家嘴", "徐家汇", "人民广场", "陆家浜", "静安", "浦东", "闵行"]}, "广州": {"aliases": ["广州", "天河", "珠江新城", "番禺", "白云区", "越秀"]}, "深圳": {"aliases": ["深圳", "福田", "南山", "前海", "罗湖", "宝安", "龙岗"]}, "杭州": {"aliases": ["杭州", "西湖", "武林", "滨江", "余杭", "萧山"]}, "南京": {"aliases": ["南京", "新街口", "河西", "江宁", "鼓楼"]}, "武汉": {"aliases": ["武汉", "光谷", "江汉路", "武昌", "汉口", "汉阳"]}, "西安": {"aliases": ["西安", "钟楼", "大雁塔", "曲江", "未央"]}, "长沙": {"aliases": ["长沙", "五一广场", "岳麓", "芙蓉", "望城"]}, "郑州": {"aliases": ["郑州", "二七", "金水", "郑东新区"]}, "天津": {"aliases": ["天津", "和平区", "河西区", "滨海新区"]}, "昆明": {"aliases": ["昆明", "五华", "盘龙", "呈贡"]}, "贵阳": {"aliases": ["贵阳", "南明", "云岩", "观山湖"]}, "福州": {"aliases": ["福州", "鼓楼区", "台江", "仓山"]}, "厦门": {"aliases": ["厦门", "思明", "湖里", "集美"]}, "南宁": {"aliases": ["南宁", "青秀", "兴宁", "西乡塘"]}, "海口": {"aliases": ["海口", "龙华区", "美兰", "琼山"]}, "哈尔滨": {"aliases": ["哈尔滨", "道里", "南岗", "松北"]}, "沈阳": {"aliases": ["沈阳", "和平", "沈河", "浑南"]}, "长春": {"aliases": ["长春", "朝阳区", "南关", "净月"]}, "大连": {"aliases": ["大连", "中山区", "沙河口", "甘井子"]}, "济南": {"aliases": ["济南", "历下", "市中区", "槐荫"]}, "青岛": {"aliases": ["青岛", "市南", "崂山", "黄岛"]}, "石家庄": {"aliases": ["石家庄", "长安区", "桥西", "裕华"]}, "太原": {"aliases": ["太原", "小店", "迎泽", "晋源"]}, "合肥": {"aliases": ["合肥", "蜀山", "包河", "庐阳"]}, "南昌": {"aliases": ["南昌", "东湖", "西湖区", "红谷滩"]}, "兰州": {"aliases": ["兰州", "城关", "七里河", "安宁"]}, "西宁": {"aliases": ["西宁", "城中", "城西", "城东"]}, "银川": {"aliases": ["银川", "兴庆", "金凤", "西夏"]}, "乌鲁木齐": {"aliases": ["乌鲁木齐", "天山区", "沙依巴克", "新市区"]}, "拉萨": {"aliases": ["拉萨", "城关区", "堆龙德庆"]}, "呼和浩特": {"aliases": ["呼和浩特", "回民区", "赛罕", "新城区"]}, "绵阳": {"aliases": ["绵阳", "涪城", "游仙"]}, "德阳": {"aliases": ["德阳", "旌阳", "广汉"]}, "南充": {"aliases": ["南充", "顺庆", "高坪"]}, "宜宾": {"aliases": ["宜宾", "翠屏", "叙州"]}, "泸州": {"aliases": ["泸州", "江阳", "龙马潭"]}, "乐山": {"aliases": ["乐山", "市中区", "峨眉山"]}, "自贡": {"aliases": ["自贡", "自流井", "贡井"]}, "内江": {"aliases": ["内江", "市中区", "东兴"]}, "眉山": {"aliases": ["眉山", "东坡", "彭山"]}, "雅安": {"aliases": ["雅安", "雨城", "名山"]}, "遂宁": {"aliases": ["遂宁", "船山", "安居"]}, "达州": {"aliases": ["达州", "通川", "达川"]}, "广元": {"aliases": ["广元", "利州", "昭化"]}, "巴中": {"aliases": ["巴中", "巴州", "恩阳"]}, "广安": {"aliases": ["广安", "广安区", "前锋"]}, "资阳": {"aliases": ["资阳", "雁江", "安岳"]}, "西昌": {"aliases": ["西昌", "凉山"]}, "攀枝花": {"aliases": ["攀枝花", "东区", "仁和"]}, "苏州": {"aliases": ["苏州", "姑苏", "工业园", "吴中"]}, "无锡": {"aliases": ["无锡", "梁溪", "滨湖", "新吴"]}, "宁波": {"aliases": ["宁波", "海曙", "鄞州", "江北区"]}, "温州": {"aliases": ["温州", "鹿城", "瓯海", "龙湾"]}, "东莞": {"aliases": ["东莞", "南城", "东城", "松山湖"]}, "佛山": {"aliases": ["佛山", "禅城", "南海", "顺德"]}, "珠海": {"aliases": ["珠海", "香洲", "金湾", "斗门"]}, "中山": {"aliases": ["中山", "石岐", "火炬"]}, "惠州": {"aliases": ["惠州", "惠城", "惠阳"]}, "汕头": {"aliases": ["汕头", "金平", "龙湖"]}, "湛江": {"aliases": ["湛江", "赤坎", "霞山"]}, "桂林": {"aliases": ["桂林", "秀峰", "象山", "七星"]}, "柳州": {"aliases": ["柳州", "城中区", "鱼峰"]}, "泉州": {"aliases": ["泉州", "鲤城", "丰泽", "晋江"]}, "常州": {"aliases": ["常州", "天宁", "钟楼区", "武进"]}, "三亚": {"aliases": ["三亚", "吉阳", "天涯", "海棠"]}}, "field_contract": {"scope_target": "本次判定的目标城市（来自请求 scope.city；未传则 null）", "location_scope": "target = 命中目标城市；other_place = 只命中其他地名；unknown = 没提地名", "in_scope": "location_scope=target 时为 true；未传 scope 时恒为 true（不过滤）", "place_evidence": "[{name, kind:'target'|'other', start, end}]，均可回查原文"}};

const input = $input.first().json || {};
const raw = String(input.chatInput ?? input.text ?? '').trim();
const sessionId = input.sessionId || null;
const norm = raw.replace(/\s+/g, '');

// ---- 城市识别：取最长命中的别名，避免"重庆"被"江北"这类短词抢走 ----
const cities = (LEXICON && LEXICON.cities) || {};
let city = null;
let hitLen = 0;
for (const [name, def] of Object.entries(cities)) {
  const names = [name].concat((def && def.aliases) || []);
  for (const alias of names) {
    if (alias && norm.includes(alias) && alias.length > hitLen) {
      city = name;
      hitLen = alias.length;
    }
  }
}

// ---- 意图 ----
const HELP_PAT = /^(帮助|help|说明|怎么用|你会什么|你能做什么|你是谁|你好|hi|hello)/i;
const QUERY_PAT = /(查一?下?|看看|有哪些|有没有|现状|快照|统计|汇总|多少|几条|几个|几成|情况|进展|占比|分布|手上有|收了|采到)/;
// 像一条微博正文的信号：链接、@某人、#话题#、【标题】、带日期的转发链
const POST_PAT = /(https?:\/\/|@[\u4e00-\u9fa5A-Za-z0-9_-]{1,20}|#[\u4e00-\u9fa5A-Za-z0-9]+#|【|】|\d+\s*月\s*\d+\s*日)/;

let intent = 'classify';
// "问现状"要同时满足两点：像在提问，且真的在问我们手上的数据（城市名 / 线索 / 诉求 / 统计）。
// 只靠"什么/怎么"会把贴进来的短微博（"这天气怎么办"）误判成提问。
const asksData = QUERY_PAT.test(norm) || /(线索|诉求|数据|统计|样本|抽样)/.test(norm);
const hasSubject = !!city || /(线索|诉求|数据|统计|样本|抽样)/.test(norm);

// ---- 采集任务：说"帮我抓/采集/爬 某地 某话题"就下单，不是判定 ----
const COLLECT_PAT = /(抓|采集|爬取|爬一下|收集|搜集|捞|拉一批|跑一批|再抓|多抓|补抓)/;
const STATUS_PAT = /(进度|跑到哪|到哪了|好了吗|完成了吗|跑完了吗|还在跑|job)/i;
const WANTS_JOB = COLLECT_PAT.test(norm) || /(下单|建个任务|开个任务)/.test(norm);

if (POST_PAT.test(raw)) intent = 'classify';        // 长得像微博正文：直接判，别被"多少"抢走
else if (STATUS_PAT.test(norm)) intent = 'status';   // 问进度
else if (WANTS_JOB) intent = 'collect';              // 下采集订单
else if (HELP_PAT.test(norm) || norm.length < 4) intent = 'help';
else if (asksData && hasSubject && raw.length <= 60) intent = 'query';

// ---- 词表里没有的地名：**也当成一个城市去采、去统计** ----
// 旧版是回一句"请先去词表加一行"，用户看着像命令没生效。
// 现在两种写法都认：
//   ① 带后缀 —— 「平顶山市」「龙泉驿区」
//   ② 不带后缀但位置很明确 —— 「平顶山现在有多少线索」「帮我抓平顶山 遮阴」
// 认出来就把字面地名当城市名（去掉"市/区/县/镇"），别名带上全称，
// 判定口径照用（run-pipeline --city/--aliases），所以统计不会全落"范围外"。
const TOPIC_WORDS = ['遮阴', '树荫', '阴凉', '纳凉', '闷热', '暴晒', '高温', '热浪', '热岛',
  '凉快', '通风', '绿化', '行道树', '乘凉', '日晒', '候车', '公园', '建筑', '道路', '地面',
  '气温', '天气', '降温', '体感', '空调', '中暑', '太阳', '水泥', '公交', '地铁', '线索',
  '诉求', '数据', '统计', '样本', '抽样'];

function guessPlace(text) {
  const suffixed = text.match(/([\u4e00-\u9fa5]{2,4})(市|区|县|镇)/);
  if (suffixed) return { name: suffixed[1], full: suffixed[1] + suffixed[2] };
  // 去掉开头的动词，避免「帮我抓平顶山遮阴」把"帮我抓"当地名
  const body = text.replace(/^(帮我|给我|请|麻烦|再|多|想)?(抓|采集|爬取|爬一下|爬|收集|搜集|捞|拉一批|跑一批)/, '');
  const lead = body.match(/^([\u4e00-\u9fa5]{2,4}?)(?=现在|目前|最近|今天|这两天|这周|有多少|有啥|有几条|的线索|这边|那边|的|热不热|怎么样)/);
  if (lead && !TOPIC_WORDS.includes(lead[1])) return { name: lead[1], full: lead[1] };
  return null;
}

let unknown_place = null;
let unknown_aliases = [];
if (!city && !POST_PAT.test(raw)) {
  const p = guessPlace(norm);
  if (p) {
    city = p.name;                                // 规范名：平顶山
    unknown_place = p.full;                       // 原话：平顶山市 / 平顶山
    unknown_aliases = [p.full, p.name].filter(Boolean);
    // "平顶山市热不热" 这种短问句别被当成要判定的微博正文
    if (intent === 'classify' && raw.length <= 25 && /(热不热|怎么样|有没有|多少|现状|线索|诉求)/.test(norm)) {
      intent = 'query';
    }
  }
}

// ---- 快照文件：按城市名推文件名，**是否真的存在交给后面的读文件节点验证** ----
// 以前这里写死"只有成都、重庆"，结果新采了别的城市它也还是回"没有"。
// 现在一律算出一个候选文件名：读得到就用，读不到（ENOENT）就自动下单去采。
let city_file = 'heat_perception.json';   // 没提城市：默认看成都（唯一同步到平台的快照）
if (city && city !== '成都') city_file = `heat_perception_${city}.json`;
let city_note = unknown_place
  ? `词表里没有「${unknown_place}」，我按字面地名采和统计（想要别名更全，可加一行到 config/place-lexicon.v2.json）`
  : (intent === 'query' && !city
      ? '这句里没看出城市名，先按成都那份快照回答；要问别的城市请带上地名（例如「重庆现在有多少线索」）'
      : '');

// ---- 主题词：把问句里的动词/城市名去掉，剩下的当主题 ----
const stop = ['查一下', '查查', '查', '看看', '有哪些', '有没有', '现状', '快照', '统计', '汇总',
  '多少条', '多少', '几条', '几个', '几成', '情况', '进展', '占比', '分布', '手上有', '收了', '采到',
  '的', '吗', '呢', '啦', '了', '和', '现在', '目前', '最近', '一共', '总共',
  '？', '?', '请', '帮我', '我想看', '想知道', '告诉你', '有多少']; 
let topic = norm;
for (const w of stop) topic = topic.split(w).join('');
if (city) {
  topic = topic.split(city).join('');
  for (const alias of ((cities[city] && cities[city].aliases) || [])) topic = topic.split(alias).join('');
}
topic = topic.slice(0, 16);

const request_id = 'chat-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);

// ---- 采集任务单：把这句话拆成"搜什么、抓多深" ----
// 两种情况会建任务单：
//   1) 用户明说"帮我抓/采集…"（intent=collect）
//   2) 用户问某地现状，但那个城市的快照读不到（intent=query + 有城市名）
//      → 先按默认参数把单子备好，等读文件节点确认"文件不存在"再真正写进队列
// 关键：地点由这句话决定。没提城市就只按关键词搜（不做城市过滤），不预设成都。
let job = null;
const auto = (intent === 'query' && !!city);
if (intent === 'collect' || auto) {
  let kw = '';
  if (auto) {
    // 自动补采时关键词必须跟"热"有关：问句里的"有多少线索"不是话题。
    // 先在原句里找热相关词，找不到就用"高温"（这也是微博上量最大的热话题词）。
    const HEAT_WORDS = ['遮阴', '树荫', '阴凉', '纳凉', '闷热', '暴晒', '高温', '热浪',
      '热岛', '凉快', '通风', '绿化', '行道树', '乘凉', '日晒'];
    for (const w of HEAT_WORDS) {
      if (norm.includes(w)) { kw = w; break; }
    }
    if (!kw) kw = '高温';
  } else {
    const junk = ['帮我', '给我', '麻烦', '请', '我要', '我想', '抓', '采集', '爬取', '爬一下', '爬',
      '收集', '搜集', '捞', '拉一批', '跑一批', '再抓', '多抓', '补抓', '下单', '建个任务', '开个任务',
      '一下', '一些', '一批', '点儿', '点', '的微博', '微博', '帖子', '评论', '内容', '数据', '线索',
      '最近', '现在', '目前', '相关', '吧', '呗', '谢谢', '好吗', '可以吗', '的', '了', '吗', '？', '?'];
    kw = norm;
    if (city) {
      kw = kw.split(city).join('');
      for (const alias of ((cities[city] && cities[city].aliases) || [])) kw = kw.split(alias).join('');
    }
    for (const w of junk) kw = kw.split(w).join('');
    kw = kw.slice(0, 20).trim() || '高温';
  }

  // "多抓点/抓深一点" → 翻页与帖子数加倍（仍受额度上限约束）
  const deep = /(多抓|抓多点|深一点|多一些|多来点|全一点|两页|2页)/.test(norm);
  // 自动补采（用户没明说要抓）默认抓 2 页，样本太小时关切点会空
  const pages = deep ? 2 : (auto ? 2 : 1);
  const top = deep ? 12 : 6;
  const comment_pages = deep ? 2 : 1;
  const query = (city ? city + ' ' : '') + kw;

  job = {
    id: 'job-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 6),
    query,
    city: city || null,
    aliases: unknown_aliases,
    keyword: kw,
    pages,
    top,
    comment_pages,
    max: 120,
    pace: auto ? 800 : 1200,
    auto,                                     // true = 因"缺快照"自动补采，不是用户下的单
    status: 'queued',
    phase: 'queued',
    message: '已下单，等待后台工人接单',
    requested_by: sessionId || 'anonymous',
    created_at: new Date().toISOString(),
  };
}

return [{
  json: {
    intent,
    city,
    city_file,
    city_note,
    topic,
    text: raw,
    norm,
    session_id: sessionId,
    request_id,
    scope: city ? { city } : null,
    job,
    unknown_place,
    unknown_aliases,
  },
}];

// 聊天窗 2d：把任务单序列化成文本，交给 convertToFile 写成文件
// 数据流：1-意图(job) → 2d-生成任务JSON(job_text) → 2d2-转成文件(二进制) → 2d3-写任务文件 → 3d-回执
const src = $('1-意图').first().json;
const job = src.job;

if (!job || !job.id) {
  return [{ json: { job_text: '{}', job_id: null } }];
}

// 任务单本身就是要被后台工人读的文件：字段少、可人工查看、可手改
const job_text = JSON.stringify(job, null, 2);

return [{
  json: {
    job_id: job.id,
    job_text,
    query: job.query,
    city: job.city,
  },
}];

// 聊天窗 3d：任务已写入队列，回执给用户（含怎么查进度）
// 数据流：2d3-写任务文件 → 3d-回执 → 聊天窗
// 两种来源：用户自己说"帮我抓…"（job.auto=false）；或问了一个没有快照的城市（job.auto=true）
const src = $('1-意图').first().json;
const job = src.job || {};
const L = [];

if (job.auto) {
  L.push('**「' + job.city + '」我手上还没有快照，已经自动下单去采了**');
  if (src.city_note) L.push('');
  if (src.city_note) L.push('> ' + src.city_note);
  L.push('');
  L.push('- 任务号：`' + (job.id || '（生成失败）') + '`');
  L.push('- 搜索词：`' + (job.query || '') + '`');
  L.push('- 抓取深度：微博 ' + (job.pages || 2) + ' 页 / 每帖最多 ' + (job.top || 6) + ' 条一级评论 × ' + (job.comment_pages || 1) + ' 页');
  L.push('');
  L.push('页面顶部的进度条会自动跟：**采微博 → 逐条判定 → 汇总成快照**，大约 2–3 分钟。');
  L.push('跑完再问我一句「' + job.city + '现在有多少线索」，就有数字了；中途问「进度」也可以。');
  L.push('');
  L.push('_这次是现场抽样采集，样本量决定结论强弱：样本小的时候，没有检出诉求不等于没有热问题。_');
  L.push('');
  L.push('_需要后台工人开着（`2-启动采集工人.cmd`）才会真的去跑。_');
} else {
  L.push('**已下单，后台开始采集**');
  L.push('');
  L.push('- 任务号：`' + (job.id || '（生成失败）') + '`');
  L.push('- 搜索词：`' + (job.query || '') + '`');
  if (job.city) L.push('- 地点范围：**' + job.city + '**（只统计命中这个城市的线索）');  else L.push('- 地点范围：**不限定城市**（这句话里没提地名，所以只按关键词搜）');
  L.push('- 抓取深度：微博 ' + (job.pages || 1) + ' 页 / 每帖最多 ' + (job.top || 6) + ' 条一级评论 × ' + (job.comment_pages || 1) + ' 页');
  L.push('');
  L.push('三步会依次跑：**采微博 → 逐条判定 → 汇总成快照**，通常 1–3 分钟。');
  L.push('问一句「进度」我就报当前到哪一步；跑完后问「' + (job.city || '') + '现在有多少线索」就能看结果。');
  L.push('');
  L.push('_采集的是公开微博与一级评论的样本，不是温度观测，也不代表受影响人数。_');
}

return [{ json: { output: L.join('\n') } }];

// 聊天窗 3e：把任务进度文件读成人话
// 数据流：2e-读进度 → 2f-进度文本(extractFromFile text → json.data) → 3e-进度 → 聊天窗
const raw = $('2f-进度文本').first().json.data;
const L = [];

let job = null;
try {
  job = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch {
  job = null;
}

const PHASE = {
  queued: '排队中（后台工人马上接单）',
  collecting: '第 1 步 / 共 3 步：采微博',
  classifying: '第 2 步 / 共 3 步：逐条判定',
  aggregating: '第 3 步 / 共 3 步：汇总快照',
  done: '全部完成',
  failed: '中途失败',
  idle: '当前没有任务',
};

if (!job || !job.id) {
  L.push('**当前没有采集任务**');
  L.push('');
  L.push('说一句「帮我抓成都 遮阴」就会下单；也可以说「进度」看正在跑的任务。');
  return [{ json: { output: L.join('\n') } }];
}

const pct = () => {
  if (job.status === 'done') return 100;
  if (!job.total) return job.phase === 'collecting' ? 15 : 30;
  return Math.min(99, Math.round(30 + (Number(job.done || 0) / Number(job.total)) * 65));
};

L.push('**任务 `' + job.id + '`**');
L.push('');
L.push('- 状态：' + (PHASE[job.phase] || job.phase || job.status || '未知'));
L.push('- 搜索词：`' + (job.query || '') + '`' + (job.city ? '（地点：' + job.city + '）' : '（不限城市）'));
if (job.posts || job.comments) L.push('- 已抓：帖子 ' + (job.posts || 0) + ' 条 / 评论 ' + (job.comments || 0) + ' 条');
if (job.total) L.push('- 判定进度：' + (job.done || 0) + ' / ' + job.total);
if (job.message) L.push('- 最近一步：' + job.message);
L.push('- 整体完成度：约 **' + pct() + '%**');

if (job.status === 'done') {
  L.push('');
  L.push('跑完了。现在可以问「' + (job.city || '') + '现在有多少线索」，或贴一条微博让我判。');
  if (job.snapshot) L.push('（快照：`' + job.snapshot + '`）');
} else if (job.status === 'failed') {
  L.push('');
  L.push('**失败原因**：' + (job.error || job.message || '未提供'));
  L.push('常见原因：微博 Cookie 过期（重新打开 Edge 登录一次再跑）、或网络被限流。');
} else {
  L.push('');
  L.push('_还在跑，过一会儿再说一次「进度」即可。_');
}

L.push('');
L.push('_这些数字是抽样抓取的条数，不是人数。_');

return [{ json: { output: L.join('\n') } }];

// 聊天窗「问现状」第 2g 步：把快照整理成两样东西
//   ① facts —— 渲染层唯一的事实来源（条数、类别、代表原文、原文链接）
//   ② model_body —— 交给大模型"组织语言"的请求体
// 关键约束：模型只负责把 facts 讲成人话，数字与原文都由这里提供，渲染层还会再校对一遍。
const ctx = $('1-意图').first().json;
const first = $input.first();

// 快照文本两种可能：上一节点已解成 json.data，或者仍是二进制 base64
let text = first.json && typeof first.json.data === 'string' ? first.json.data : null;
if (!text) {
  const bin = first.binary && first.binary.data && first.binary.data.data;
  if (!bin) return [{ json: { snapshot_missing: true, city: ctx.city || null, facts: null, model_body: null } }];
  text = Buffer.from(bin, 'base64').toString('utf8');
}

let snap;
try {
  snap = JSON.parse(text);
} catch (e) {
  return [{ json: { snapshot_broken: true, error: e.message, facts: null, model_body: null } }];
}

const c = snap.counts || {};
const cityLabel = ctx.city || (snap.source && snap.source.city) || '成都';

// ---- 原文链接：来源唯一，就是快照里每条记录的 source_url（采集器写入 m.weibo.cn/detail/<id>）
// 缺失 / 空串 / 不是 http 开头 → 一律当成"原文不可访问"，绝不拼接猜测的链接
function normUrl(u) {
  if (typeof u !== 'string') return null;
  const s = u.trim();
  if (!/^https?:\/\/[^\s]+$/i.test(s)) return null;
  return s;
}

const DIR_ZH = { discomfort: '不适', improvement: '改善', mixed: '混合', neutral: '中性', unclear: '未说明', unknown: '未说明' };
// 体验标签、空间诉求的中文名：只在这里维护一份，渲染层不要再手抄
const EXP_ZH = { hot: '炎热', muggy: '闷热', sun_exposure: '暴晒', cool: '凉爽', mixed: '混合', unspecified: '未说明' };
const DEMAND_ZH = {
  shade_deficit: '需要遮阴',
  ventilation: '需要通风',
  waiting_comfort: '候车/等候条件要改善',
  stay_comfort: '停留时要更舒服',
  water_or_cooling_facility: '需要饮水/降温设施',
};
function dirZh(dir) {
  if (!dir || typeof dir !== 'object') return '';
  return Object.entries(dir)
    .sort((a, b) => b[1] - a[1])
    .map(([k, v]) => DIR_ZH[k] || k)
    .join('、');
}

function pickReps(list, max) {
  const out = [];
  const seen = new Set();
  for (const r of list || []) {
    if (!r || !r.excerpt) continue;
    const key = String(r.excerpt).slice(0, 40);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({
      excerpt: String(r.excerpt).slice(0, 80),
      url: normUrl(r.source_url),
      published_at: r.published_at || null,
      item_id: r.item_id || null,
    });
    if (out.length >= max) break;
  }
  return out;
}

// ---- 关切点（有具体空间诉求）----
// "other"（一般性热感受）不是空间诉求，归到下面的体验观察里，避免同一个类别在两处重复计数
const events = (Array.isArray(snap.events) ? snap.events : [])
  .filter((e) => e && e.demand_topic !== 'other')
  .slice()
  .sort((a, b) => (b.item_count || 0) - (a.item_count || 0))
  .map((e) => ({
    topic_zh: e.demand_topic_zh || e.demand_topic || '未分类',
    topic: e.demand_topic || null,
    count: Number(e.item_count || 0),
    dir: dirZh(e.evaluation_direction),
    place: e.place_hint || null,
    first_at: e.first_published_at || null,
    last_at: e.last_published_at || null,
    reps: pickReps([e.representative, ...(Array.isArray(e.representatives) ? e.representatives : [])], 3),
  }));

// ---- 体验观察（没有具体空间诉求，但是民意）----
// 把 events 里的 "other" 也并进来（同一个维度，只在该出现的地方出现一次）
const otherEvents = (Array.isArray(snap.events) ? snap.events : []).filter((e) => e && e.demand_topic === 'other');
const obsRaw = (Array.isArray(snap.observations) ? snap.observations : []).slice();
for (const e of otherEvents) {
  const hit = obsRaw.find((o) => o && o.demand_topic === 'other');
  if (hit) {
    const seen = new Set((hit.examples || []).map((x) => x.item_id));
    const extra = [e.representative].filter((r) => r && !seen.has(r.item_id));
    hit.examples = [...(hit.examples || []), ...extra];
    hit.item_count = Math.max(hit.item_count || 0, e.item_count || 0);
  } else {
    obsRaw.push({ demand_topic: 'other', demand_topic_zh: e.demand_topic_zh, item_count: e.item_count, evaluation_direction: e.evaluation_direction, examples: [e.representative].filter(Boolean) });
  }
}
const observations = obsRaw
  .slice()
  .sort((a, b) => (b.item_count || 0) - (a.item_count || 0))
  .map((o) => ({
    topic_zh: o.demand_topic_zh || o.demand_topic || '未分类',
    topic: o.demand_topic || null,
    count: Number(o.item_count || 0),
    dir: dirZh(o.evaluation_direction),
    reps: pickReps(o.examples, 2),
  }));

const allReps = [...events.flatMap((e) => e.reps), ...observations.flatMap((o) => o.reps)];

// ---- 线索清单：逐条给「原文摘要 / 位置 / 体验 / 诉求 / 原文链接」----
// 五样都从快照的 items 里取；缺哪样就写"未说明"，绝不替它编一个
function expZh(arr) {
  const a = Array.isArray(arr) ? arr.filter(Boolean).map((v) => EXP_ZH[v] || v) : [];
  return [...new Set(a)].join('、') || '未说明';
}
function demandZhOf(it) {
  const a = Array.isArray(it.spatial_demands) ? it.spatial_demands.filter(Boolean).map((v) => DEMAND_ZH[v] || v) : [];
  if (a.length) return [...new Set(a)].join('、');
  // 没有空间诉求时，用话题兜底；话题本身是"一般性热感受"就明说
  const t = it.demand_topic_zh || it.demand_topic || '';
  if (!t || it.demand_topic === 'other') return '无具体空间诉求（只说体感）';
  return `无具体空间诉求（话题：${t}）`;
}
function placeOf(it) {
  const ev = Array.isArray(it.place_evidence) ? it.place_evidence : [];
  // 只认"目标城市"的地名（target/study_area）；顺带提到的外地城市不算这条线索的位置
  const targets = ev.filter((p) => p && (p.kind === 'target' || p.kind === 'study_area')).map((p) => p.name).filter(Boolean);
  const names = targets.length ? targets : ev.map((p) => (p && p.name) || '').filter(Boolean);
  if (names.length) return [...new Set(names)].slice(0, 3).join('、');
  const scope = it.scope_target || null;
  if (scope) return `${scope}（具体地点未指明）`;
  return '未指明具体地点';
}
function dirOf(it) {
  const d = it.evaluation_direction;
  return (d && (DIR_ZH[d] || d)) || '未说明';
}
// 展示上限：单一来源 config/answer-caps.json（构建时注入），改完重跑 build-chat-workflow.py 再部署
const CAPS = {"caps_version": "c1", "_note": "聊天回答里各列表的展示上限。改完要重跑 scripts/build-chat-workflow.py 再部署。", "leads": 40, "lead_excerpt_chars": 120, "reps_per_category": 3, "observation_categories": 8, "needs": 5} || {};
const CAP_LEADS = Number(CAPS.leads) > 0 ? Number(CAPS.leads) : 40;
const CAP_EXCERPT = Number(CAPS.lead_excerpt_chars) > 0 ? Number(CAPS.lead_excerpt_chars) : 120;

const allLeads = (Array.isArray(snap.items) ? snap.items : [])
  .filter((it) => it && it.heat_relevance === 'relevant' && it.in_scope !== false)
  .sort((a, b) => {
    const dc = Number(b.confidence || 0) - Number(a.confidence || 0);
    if (dc) return dc;
    return String(b.published_at || '').localeCompare(String(a.published_at || ''));
  });
const lead_total = allLeads.length;
const leads = allLeads
  .slice(0, CAP_LEADS)
  .map((it) => ({
    item_id: it.item_id || null,
    // 摘要：优先用判定时截下来的那句原文（evidence 片段），没有才退回正文开头
    excerpt: String(it.excerpt || it.text || '').replace(/\s+/g, ' ').slice(0, CAP_EXCERPT),
    place: placeOf(it),
    experience: expZh(it.experience_tags),
    demands: demandZhOf(it),
    direction: dirOf(it),
    topic_zh: it.demand_topic_zh || it.demand_topic || null,
    published_at: it.published_at || null,
    url: normUrl(it.source_url),
    confidence: it.confidence ?? null,
    review_status: it.review_status || null,
  }));

// ---- 温度感受：先按体感标签数一遍（这是"从温度感受入手"的那一步，纯规则、可复现）----
// 每条帖子可能同时命中多个感受标签，所以这里的合计会大于帖子条数，只是"提及次数"
const FEEL_DEFS = [
  { zh: '炎热', tags: ['hot'] },
  { zh: '闷热', tags: ['muggy'] },
  { zh: '暴晒', tags: ['sun_exposure'] },
  { zh: '凉爽/改善', tags: ['cool'] },
];
const scopeItems = (Array.isArray(snap.items) ? snap.items : []).filter(
  (it) => it && it.heat_relevance === 'relevant' && it.in_scope !== false,
);
const heatFeel = FEEL_DEFS.map((d) => ({
  感受: d.zh,
  条数: scopeItems.filter((it) => (it.experience_tags || []).some((t) => d.tags.includes(t))).length,
})).filter((x) => x.条数 > 0);
// 时间范围：回答里要能说清"这批帖子是多久以内的"
const dates = scopeItems.map((it) => it.published_at).filter(Boolean).sort();
const timeRange = {
  from: dates.length ? String(dates[0]).slice(0, 10) : null,
  to: dates.length ? String(dates[dates.length - 1]).slice(0, 10) : null,
  window_days: (snap.source && snap.source.window_days) || null,
};

const facts = {
  city: cityLabel,
  snap_city: (snap.source && snap.source.city) || null,
  mode: snap.mode || 'unknown',
  generated_at: snap.generated_at || null,
  city_note: ctx.city_note || null,
  counts: {
    raw_posts: c.raw_posts ?? null,
    raw_comments: c.raw_comments ?? null,
    classified_items: c.classified_items ?? null,
    in_scope_items: c.in_scope_items ?? c.in_study_area_items ?? null,
    unique_contents: c.unique_contents ?? null,
    public_demand_items: c.public_demand_items ?? null,
    out_of_scope_items: c.out_of_scope_items ?? null,
    place_unknown_items: c.place_unknown_items ?? null,
  },
  limits: (Array.isArray(snap.limits) ? snap.limits : []).slice(0, 4),
  demands: events,
  observations,
  heat_feel: heatFeel,
  time_range: timeRange,
  leads,
  lead_total,
  caps: {
    leads: CAP_LEADS,
    reps_per_category: Number(CAPS.reps_per_category) > 0 ? Number(CAPS.reps_per_category) : 3,
    observation_categories: Number(CAPS.observation_categories) > 0 ? Number(CAPS.observation_categories) : 8,
    needs: Number(CAPS.needs) > 0 ? Number(CAPS.needs) : 5,
  },
  model_info: {
    model: 'deepseek-flash',
    provider: 'DeepSeek（OpenAI 兼容接口 /chat/completions）',
    temperature: 0.3,
    max_tokens: 900,
    classify_model: 'deepseek-flash',
    classify_temperature: 0.2,
    rules_version: (snap.meta && snap.meta.rules_version) || 'r1',
    taxonomy_version: (snap.meta && snap.meta.taxonomy_version) || 't1',
    classifier_version: (snap.meta && snap.meta.classifier_version) || 'c1-model',
    place_version: (snap.meta && snap.meta.place_version) || 'p2',
  },
  link_stats: {
    leads: leads.length,
    reps: allReps.length,
    with_url: leads.filter((r) => r.url).length,
    missing: leads.filter((r) => !r.url).length,
  },
};

// ---- 给模型的材料：只给结论与原文，明确要求"不许改数字、不许编原文"----
const material = {
  city: facts.city,
  counts: facts.counts,
  温度感受: heatFeel,
  demands: events.map((e) => ({ 类别: e.topic_zh, 条数: e.count, 倾向: e.dir, 地点: e.place, 代表原文: e.reps.map((r) => r.excerpt) })),
  observations: observations.map((o) => ({ 类别: o.topic_zh, 条数: o.count, 倾向: o.dir, 例子: o.reps.map((r) => r.excerpt) })),
  时间范围: timeRange,
};

const system = [
  '你是微博热感知助手的"讲人话"环节。给你一份已经抽取好的统计结果，你要把它组织成普通读者能看懂的中文。',
  '',
  '硬性规则：',
  '1. 只能使用给定材料里的数字和原文，不得新增、不得改写条数、不得编造原文，不得推测受影响人数；',
  '2. 不要使用"热相关性""空间诉求""分类维度""抽样口径"这类内部术语，改用日常说法（比如"抱怨没有遮阴""说等车太晒"）；',
  '3. 先说温度感受（热、闷、暴晒、凉快各有多少人提），再说这些感受集中在什么场景/诉求上；不要输出链接、不要输出 Markdown 标题或列表，只输出 JSON；',
  '4. 如果材料里没有具体诉求，就如实说"这批样本里没看到明确的改造诉求，多是笼统的热感受"。',
  '',
  '输出 JSON，字段如下：',
  '{',
  '  "summary": "一两句大白话：先讲温度感受（哪种感受最多），再讲集中在哪里，不超过 80 字",',
  '  "categories": [{"类别": "与材料中类别完全一致", "一句话": "这条类别用大白话解释，不超过 40 字"}],',
  '  "needs": ["从材料归纳出的可落地需求，最多 3 条，每条不超过 30 字"],',
  '  "caveat": "一句话提醒这不是温度观测、不代表人数"',
  '}',
].join('\n');

const model_body = {
  model: 'deepseek-flash',
  temperature: 0.3,
  max_tokens: 900,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: '材料如下（JSON）：\n' + JSON.stringify(material, null, 2) },
  ],
};

return [{ json: { facts, model_body, city: cityLabel } }];

// 聊天窗「问现状」第 3a 步：渲染最终回答
// 输入两种可能：① 大模型回的 JSON（choices[0].message.content）② 模型失败（节点 onError 透传上来的 error）
// 事实一律取自 2g 节点的 facts；模型只贡献"一句话总结""类别解释""需求归纳"这些措辞。
// 只要模型给的类别不在 facts 里、或者模型说了别的数字，一律以 facts 为准（模型不得改条数）。
const ctx = $('1-意图').first().json;
const up = $('2g-构造摘要').first().json;
const facts = up && up.facts;

// 快照读不到 / 不是合法 JSON：交给后面的 If-缺快照? 决定（有城市名就去自动下单采集）
if (!facts) {
  return [{ json: { output: '', snapshot_missing: true, city: (up && up.city) || ctx.city || null } }];
}

// ---------- 1. 取模型输出（失败就退化成规则摘要，不编造）----------
let ai = null;
let ai_error = null;
try {
  const body = $input.first().json || {};
  if (body.error) {
    ai_error = body.error.message || body.error.code || 'model_error';
  } else {
    const content = body.choices && body.choices[0] && body.choices[0].message && body.choices[0].message.content;
    if (content) {
      const parsed = JSON.parse(content);
      if (parsed && typeof parsed === 'object') ai = parsed;
    } else {
      ai_error = 'empty_model_response';
    }
  }
} catch (e) {
  ai_error = 'parse_failed: ' + e.message;
}

// ---------- 2. 事实与措辞的校对 ----------
const c = facts.counts || {};
const FCAPS = (facts && facts.caps) || {};
const capOf = (k, d) => (Number(FCAPS[k]) > 0 ? Number(FCAPS[k]) : d);
const demandCats = (facts.demands || []).filter((e) => e.count > 0);
const obsCats = (facts.observations || []).filter((o) => o.count > 0);

// 模型给的类别解释（按类别中文名匹配；多了的丢掉，少了的不补）
const catExplain = {};
if (ai && Array.isArray(ai.categories)) {
  for (const item of ai.categories) {
    if (!item) continue;
    const key = String(item['类别'] || item.category || item.name || '').trim();
    const val = String(item['一句话'] || item.explain || item.description || '').trim();
    if (key && val) catExplain[key] = val;
  }
}

// 一句话总结：模型给了就用；没有就用事实拼一句同样通俗的
function fallbackSummary() {
  if (!demandCats.length) {
    const total = c.in_scope_items || c.in_study_area_items || 0;
    return `这批样本里没看到明确的改造诉求，${total} 条内容多是笼统的热感受，另有 ${c.unique_contents || 0} 条去重后的内容可看。`;
  }
  const top = demandCats[0];
  const rest = demandCats.length > 1 ? `，其次是「${demandCats[1].topic_zh}」（${demandCats[1].count} 条）` : '';
  return `大家主要在说「${top.topic_zh}」（${top.count} 条）${rest}。`;
}
const summary = (ai && typeof ai.summary === 'string' && ai.summary.trim()) ? ai.summary.trim() : fallbackSummary();

// 需求归纳：模型给了就取前 3 条；没有就从类别里直接生成
let needs = [];
if (ai && Array.isArray(ai.needs)) {
  needs = ai.needs.map((x) => String(x).trim()).filter(Boolean).slice(0, 3);
}
if (!needs.length) {
  needs = demandCats.slice(0, capOf('needs', 3)).map((e) => `${e.topic_zh}${e.place ? '（' + e.place + '）' : ''}`);
}

// ---------- 3. 原文链接：有就点得开，没有就明说 ----------
function linkOf(rep) {
  if (rep && rep.url) return `[原文](${rep.url})`;
  return '（原文不可访问）';
}
function quoteOf(rep) {
  return rep ? `「${String(rep.excerpt).replace(/\s+/g, ' ').slice(0, 70)}」` : '';
}

const modeZh = facts.mode === 'historical_sample' ? '历史抽样回放' : (facts.mode || '未知模式');
const L = [];

// ---------- 4. 排版：一句话 / 线索清单 / 分类明细 / 需求 / 边界 ----------
// 快照城市和用户问的城市不一致时，先说清楚，别让人以为答的是别处
if (facts.snap_city && ctx.city && facts.snap_city !== ctx.city) {
  L.push(`> ⚠️ 你问的是「${ctx.city}」，但手上这份快照是「${facts.snap_city}」的，下面这些都是${facts.snap_city}的数据。`);
  L.push('');
}
L.push(`**${facts.city} · 微博热感知（${modeZh}）**`);
if (facts.city_note) L.push(`_${facts.city_note}_`);
L.push('');
L.push(`**一句话**：${summary}`);
const feel = Array.isArray(facts.heat_feel) ? facts.heat_feel : [];
if (feel.length) {
  L.push('');
  L.push('**温度感受**：' + feel.map((f) => `${f.感受} ${f.条数} 条`).join(' · ') + '（按帖子里的体感标签数，同一条可能命中多种）');
}
L.push('');

// ---------- 5. 线索清单：每条都按「摘要 / 位置 / 体验 / 诉求 / 原文链接」给 ----------
const leads = Array.isArray(facts.leads) ? facts.leads : [];
if (leads.length) {
  const leadTotal = Number(facts.lead_total) || leads.length;
  const more = leadTotal > leads.length ? `；另有 ${leadTotal - leads.length} 条未展开，全量在平台侧栏` : '';
  L.push(`**线索清单**（共 ${leadTotal} 条，这里列 ${leads.length} 条，按可信度排序${more}）`);
  leads.forEach((ld, i) => {
    L.push('');
    L.push(`**${i + 1}.** ${ld.excerpt}`);
    L.push(`- 位置：${ld.place}`);
    L.push(`- 体验：${ld.experience}（${ld.direction}）`);
    L.push(`- 诉求：${ld.demands}${ld.topic_zh ? ` · 归类：${ld.topic_zh}` : ''}`);
    const when = ld.published_at ? ` · ${String(ld.published_at).slice(0, 10)}` : '';
    L.push(`- 原文：${ld.url ? `[点开微博](${ld.url})` : '（原文不可访问）'} · 可信度 ${ld.confidence ?? '-'}${when}`);
  });
  L.push('');
} else {
  L.push('**线索清单**：这批样本里没有检出符合条件（落在本市、判为热相关）的单条线索。');
  L.push('');
}

L.push('**分类明细**（类别 · 条数 · 代表原文，点「原文」可跳转核对）');
if (!demandCats.length) {
  L.push('- 这批样本里没有检出带具体地点的改造诉求。');
} else {
  for (const e of demandCats) {
    const meta = [e.dir ? `倾向：${e.dir}` : '', e.place ? `地点：${e.place}` : ''].filter(Boolean).join(' · ');
    L.push(`- **${e.topic_zh}** · ${e.count} 条${meta ? ' · ' + meta : ''}`);
    if (catExplain[e.topic_zh]) L.push(`  - 说的是：${catExplain[e.topic_zh]}`);
    for (const rep of (e.reps || []).slice(0, capOf('reps_per_category', 2))) {
      L.push(`  - ${linkOf(rep)} ${quoteOf(rep)}`);
    }
    if (!(e.reps || []).length) L.push('  - （原文不可访问）这一类没有可回查的原文。');
  }
}

if (obsCats.length) {
  L.push('');
  L.push('**体验观察**（不是改造诉求，但同样是民意）');
  for (const o of obsCats.slice(0, capOf('observation_categories', 5))) {
    const head = `- **${o.topic_zh}** · ${o.count} 条${o.dir ? '（倾向：' + o.dir + '）' : ''}`;
    L.push(head);
    const rep = (o.reps || [])[0];
    if (rep) L.push(`  - ${linkOf(rep)} ${quoteOf(rep)}`);
  }
}

L.push('');
L.push('**这些线索属于哪些需求**');
for (const n of needs) L.push(`- ${n}`);

// 数据口径一行（保留可追溯性，但不堆术语）
L.push('');
const tr = facts.time_range || {};
const trText = (tr.from && tr.to ? `${tr.from} ~ ${tr.to}` : '时间未知') + (tr.window_days ? `（只算最近 ${tr.window_days} 天）` : '');
L.push(`_样本：原始 ${c.raw_posts ?? '?'} 帖 / ${c.raw_comments ?? '?'} 条评论 → 判定 ${c.classified_items ?? '?'} 条 → 落在${facts.city} ${c.in_scope_items ?? '?'} 条 → 去重后 ${c.unique_contents ?? '?'} 条；发布时间 ${trText}；范围外 ${c.out_of_scope_items ?? '?'} 条、地点待定 ${c.place_unknown_items ?? '?'} 条。_`);
const ls = facts.link_stats || {};
L.push(`_原文链接：${ls.with_url ?? 0} 条可跳转${ls.missing ? `，${ls.missing} 条已缺失或已删除（标注为「原文不可访问」）` : ''}。_`);

if (ai && ai.caveat) {
  L.push('');
  L.push(`> ${String(ai.caveat).slice(0, 120)}`);
}
if (ai_error) L.push('');
if (ai_error) L.push(`_（这次没能请大模型润色，上面是按规则拼的；原因：${ai_error}）_`);
L.push(`_快照生成于 ${facts.generated_at || '未知时间'}。_`);
// 模型透明：这条回答里"哪一段是谁写的"必须能追溯
const mi = facts.model_info || {};
L.push(`_模型：${mi.model || 'deepseek-flash'}（${mi.provider || 'DeepSeek'}）· 判定 T=${mi.classify_temperature ?? 0.2} / 摘要 T=${mi.temperature ?? 0.3} max_tokens=${mi.max_tokens ?? 900} · 规则 ${mi.rules_version || 'r1'} · 分类器 ${mi.classifier_version || 'c1-model'} · 词表 ${mi.taxonomy_version || 't1'} · 地名词库 ${mi.place_version || 'p2'}_`);

return [{ json: { output: L.join('\n'), ai_used: !!ai, ai_error } }];

// 聊天窗 3a2：快照读到了，把 3a 的排版结果原样往下传
// 为什么需要这个节点：If 节点自己的输出没有 output 字段，聊天窗（responseMode=lastNode）会显示空消息。
// 它不是逻辑，只是一次"搬运"。
return [{ json: $('3a-汇总').first().json }];

// 聊天窗第 3b 步：把 03 契约服务返回的单条判定结果说成人话
// 输入：HTTP 节点调 http://127.0.0.1:5678/webhook/weibo-demand/v1 的响应
const ctx = $('1-意图').first().json;
const resp = $input.first().json || {};

const fail = (msg) => [{ json: { output: msg } }];

// ---- 出错也要说清楚是哪一类错 ----
// 注意：成功响应里 errors 可能是空数组，空数组 truthy，必须看长度
const errs = Array.isArray(resp.errors) ? resp.errors : [];
if (resp.status === 'error' || errs.length) {
  const lines = ['**没能判定**（' + (resp.request_id || '-') + '）'];
  for (const e of errs.slice(0, 5)) {
    lines.push(`- \`${e.code}\`：${e.message}${e.path ? ' @ ' + e.path : ''}${e.retryable ? '（可重试）' : '（不可重试）'}`);
  }
  if (!errs.length) lines.push('- ' + JSON.stringify(resp).slice(0, 300));
  return fail(lines.join('\n'));
}

const result = resp.result || {};
const item = (Array.isArray(result.items) && result.items[0]) || result.item || result;
if (!item || !item.item_id && !item.heat_relevance) {
  return fail('返回体里没有找到判定条目：' + JSON.stringify(resp).slice(0, 300));
}

// 标签中文名来自 config/taxonomy.v1.json（构建时注入），别在这里手抄一份，否则迟早和词表不一致
const LBL = {"heat_relevance": {"relevant": "相关", "needs_review": "待核实", "irrelevant": "不相关"}, "evaluation_direction": {"discomfort": "不适", "improvement": "改善", "neutral": "中性", "mixed": "混合", "unclear": "不明确"}, "activity_scene": {"walking": "步行", "cycling": "骑行", "waiting": "等候", "leisure": "游憩", "outdoor_work": "室外工作", "other": "其他", "unspecified": "未说明"}, "demand_topic": {"shade_deficit": "缺少遮阴", "tree_canopy": "树荫/绿化覆盖诉求", "waiting_transit": "候车与换乘暴晒", "walking_route": "步行与通行环境", "plaza_leisure": "广场与开放空间休憩", "campus_school": "校园与学校接送", "park_greenway": "公园与绿道体验", "outdoor_work": "室外作业条件", "water_cooling_facility": "饮水与降温设施", "ventilation_stillness": "通风与闷热", "surface_heat": "地面/铺装辐射热", "positive_cooling": "降温改善的积极体验", "other": "其他或无法归类"}, "content_types": {"firsthand": "亲历体验", "relay": "转述", "suggestion": "改造建议", "forecast": "天气预报", "news": "新闻转载", "ad": "广告", "unknown": "无法判断"}, "experience_tags": {"hot": "炎热", "muggy": "闷热", "sun_exposure": "暴晒", "cool": "凉爽", "mixed": "混合", "unspecified": "未说明"}, "spatial_demands": {"shade_deficit": "遮阴不足", "ventilation": "通风诉求", "waiting_comfort": "候车条件", "stay_comfort": "停留条件", "water_or_cooling_facility": "饮水或降温设施诉求"}};
const KIND_ZH = { target: '查询城市', other_place: '范围外', study_area: '研究区' };

const zhOf = (dim, v) => {
  const m = (LBL && LBL[dim]) || {};
  return m[v] || KIND_ZH[v] || v || '-';
};
const list = (dim, a) => (Array.isArray(a) && a.length ? a.map((v) => zhOf(dim, v)).join('、') : '-');

const h = item.place || {};
const ev = (item.evidence_spans || []).map((s) => s.text || s.quote || '').filter(Boolean);
const notes = Array.isArray(item.notes) ? item.notes : [];

// 一句话：把标签拼成日常说法，别让读者先学一遍词表
const topicZh = item.demand_topic_zh || zhOf('demand_topic', item.demand_topic);
const dirZh = zhOf('evaluation_direction', item.evaluation_direction);
const demandZh = list('spatial_demands', item.spatial_demands);
const isDemand = item.is_public_demand === true;
let gist;
if (item.heat_relevance === 'irrelevant') {
  gist = '这句话不是在说热，和热环境无关。';
} else if (isDemand) {
  gist = `这句话是在提需求：说的是「${topicZh}」，希望能改的地方是${demandZh === '-' ? '（没写具体）' : demandZh}，感受偏${dirZh}。`;
} else {
  gist = `这句话是在讲体感：${topicZh}，感受偏${dirZh}，没提具体要改哪儿。`;
}

const L = [];
L.push(`**这句话说了什么**：${gist}`);
L.push('');
L.push(`**判定结果**（${resp.request_id || '-'}）`);
// 五件事按用户要的顺序给：摘要 → 位置 → 体验 → 诉求 → 原文链接
L.push(`- 原文摘要：「${String(item.excerpt || item.text || ctx.text || '').replace(/\s+/g, ' ').slice(0, 90)}」`);
const placeName = [h.name, ...(Array.isArray(item.place_evidence) ? item.place_evidence.map((p) => p && p.name) : [])]
  .filter(Boolean)
  .filter((v, i, a) => a.indexOf(v) === i)
  .join('、');
const kindZh = h && h.kind ? zhOf('kind', h.kind) : '';
const scopeZh = item.in_scope === true ? '在查询范围内' : item.in_scope === false ? '不在查询范围内' : '';
const placeTail = [kindZh, scopeZh].filter(Boolean).join(' · ');
if (placeName) {
  L.push(`- 位置：${placeName}${placeTail ? `（${placeTail}）` : ''}`);
} else if (item.scope_target) {
  L.push(`- 位置：${item.scope_target}（原文没写具体地点）`);
} else {
  L.push('- 位置：原文里没识别出具体地点');
}
L.push(`- 体验：${list('experience_tags', item.experience_tags)}（倾向：${dirZh} · 场景：${zhOf('activity_scene', item.activity_scene)}）`);
L.push(`- 诉求：${demandZh === '-' ? '只说体感，没提出要改什么' : demandZh}${topicZh ? ` · 归类：${topicZh}` : ''}`);
// 粘贴进来的文本本身没有链接：明说，不伪造
L.push('- 原文链接：（这条是你粘贴的文本，没有可跳转的链接；可在微博里搜这句话核对）');
L.push('');
L.push(`- 和热有关吗：**${zhOf('heat_relevance', item.heat_relevance)}** · 这是哪种说法：${list('content_types', item.content_types)}`);
L.push(`- 把握有多大：${item.confidence ?? '-'}（${item.confidence_level || '-'}）· 需人工复核：${item.needs_review ? '是' : '否'}`);
if (ev.length) {
  L.push('');
  L.push('**证据片段（可在原文里对上号）**');
  for (const s of ev.slice(0, 4)) L.push(`- 「${String(s).slice(0, 80)}」`);
}
if (notes.length) {
  L.push('');
  L.push('**判定说明**：' + notes.join('；'));
}
L.push('');
L.push('_这是对单条文本的判定：不代表温度观测，也不代表人数。_');
L.push('_模型：deepseek-flash（DeepSeek /chat/completions）· 判定 T=0.2 max_tokens=3000 · 分类器 c1-model · 规则 r1_');

return [{ json: { output: L.join('\n') } }];

// 聊天窗兜底：用户没说清要干什么时给用法（不联网、不花钱）
const ctx = $('1-意图') ? $('1-意图').first().json : {};
const text = (ctx && ctx.text) || '';

const L = [];
// 打招呼：先回一句人话，再给用法
const isGreeting = /^(你好|您好|在吗|hi|hello|嗨|哈喽)/i.test(String(text).trim());
if (isGreeting) {
  L.push('你好。我是微博民意助理，可以帮你把公开微博读成可核查的线索。');
  L.push('');
}

// 说了「某某市」但词表里没有这个地名：默认已经按字面地名去采了（chat-1 会把它当城市），
// 这里只在"没走采集分支"时兜底提示一句，别让用户以为命令没生效。
if (ctx.unknown_place && !ctx.job) {
  const name = String(ctx.unknown_place).replace(/[市|区|县|镇]$/, '');
  L.push(`「${ctx.unknown_place}」不在城市词表里，但可以直接按字面地名采：`);
  L.push('');
  L.push(`- 发「**帮我抓${name} 遮阴**」→ 我按 \`${name}\` 去抓并统计（别名自动带上「${ctx.unknown_place}」）；`);
  L.push(`- 或问「**${name}现在有多少线索**」→ 没快照会自动补采，进度条会走，约 2–3 分钟。`);
  L.push('');
  L.push(`_想把别名补全（让「${name}」也命中「${ctx.unknown_place}」以外的叫法），在 \`config/place-lexicon.v2.json\` 的 \`cities\` 里加一行即可：_`);
  L.push('```json');
  L.push(`"${name}": { "aliases": ["${ctx.unknown_place}"] }`);
  L.push('```');
  return [{ json: { output: L.join('\n') } }];
}

if (text && !isGreeting) L.push(`没看懂「${String(text).slice(0, 30)}」想让我做什么。`);
L.push('');
L.push('**两种用法**');
L.push('1. **问现状**（读已有快照；没有就自动补采，约 2–3 分钟）：');
L.push('   - `查成都 遮阴`、`重庆 候车 现状`、`北京有多少条诉求`');
L.push('2. **贴一条微博**（调模型判定，约 3–8 秒）：');
L.push('   - 直接粘贴正文，例如：`太阳晒得人眼睛都睁不开，树荫一点都没有`');
L.push('');
L.push('**能看出什么**');
L.push('- 是否与热相关、内容类型（亲历/转述/建议/广告…）、体验标签（炎热/暴晒/闷热/凉爽）、空间诉求（遮阴不足/候车条件/通风…）、评价方向（不适/改善）');
L.push('- 每条结论都带「证据片段」，可以回到原文核对');
L.push('');
L.push('**不能做什么**');
L.push('- 不是温度观测，也不代表受影响人数；没有线索不等于没有热问题');
L.push('- 地点范围由你的问题决定，不预设城市；词表（`config/place-lexicon.v2.json`）里没有的地名，也能按字面地名直接采和统计');
L.push('- 采集需要微博 Cookie，且依赖后台工人（`2-启动采集工人.cmd`）在本机跑');

return [{ json: { output: L.join('\n') } }];
